import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as i,af as r}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Pi Agent","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/pi-agent.md","filePath":"products/ai-coding/pi-agent.md","lastUpdated":1780925353000}'),o={name:"products/ai-coding/pi-agent.md"};function n(l,t,d,s,p,h){return i(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="pi-agent" tabindex="-1">Pi Agent <a class="header-anchor" href="#pi-agent" aria-label="Permalink to &quot;Pi Agent&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>Pi Agent 是一个极简主义的 coding agent harness，由开发者 <a href="https://github.com/badlogic" target="_blank" rel="noreferrer">mariozechner</a>（曾开发 Sitegeist 等项目）历时三年打造。</p><p>作者在深度使用 Claude Code、Cursor 等工具后，发现这些工具功能日益臃肿、系统 prompt 和工具频繁变更、行为不可预测。因此他决定打造一个完全透明、<strong>固执己见</strong>（opinionated）且可预测的替代品——如果不需要，就不 built。</p><h2 id="核心设计理念" tabindex="-1">核心设计理念 <a class="header-anchor" href="#核心设计理念" aria-label="Permalink to &quot;核心设计理念&quot;">​</a></h2><h3 id="minimalist-philosophy" tabindex="-1">Minimalist Philosophy <a class="header-anchor" href="#minimalist-philosophy" aria-label="Permalink to &quot;Minimalist Philosophy&quot;">​</a></h3><blockquote><p>&quot;If I don&#39;t need it, it won&#39;t be built.&quot;</p></blockquote><p>不做不需要的功能。80% 不常用的功能宁可删掉。</p><h3 id="context-engineering-is-paramount" tabindex="-1">Context Engineering is Paramount <a class="header-anchor" href="#context-engineering-is-paramount" aria-label="Permalink to &quot;Context Engineering is Paramount&quot;">​</a></h3><p><strong>上下文工程至关重要</strong>。精确控制进入模型 context 的内容，才能得到更好的输出，尤其在写代码场景。现有 harness 在背后注入内容，且在 UI 中完全不 surface——这是不可接受的。</p><h3 id="full-transparency" tabindex="-1">Full Transparency <a class="header-anchor" href="#full-transparency" aria-label="Permalink to &quot;Full Transparency&quot;">​</a></h3><p>完全透明可溯。开发者需要能够检查与模型交互的每个环节，包括 session 格式（可后处理）、替代 UI 构建能力等。</p><h3 id="opinionated-predictable" tabindex="-1">Opinionated &amp; Predictable <a class="header-anchor" href="#opinionated-predictable" aria-label="Permalink to &quot;Opinionated &amp; Predictable&quot;">​</a></h3><p>固执且可预测。不做 backwards compatibility 的包袱，API 从一开始就是干净的设计。</p><h2 id="技术架构" tabindex="-1">技术架构 <a class="header-anchor" href="#技术架构" aria-label="Permalink to &quot;技术架构&quot;">​</a></h2><p>Pi Agent 由 4 个核心包组成，均在 <a href="https://github.com/badlogic/pi-mono" target="_blank" rel="noreferrer">pi-mono</a> 仓库中维护：</p><h3 id="pi-ai-—-统一-llm-api" tabindex="-1">pi-ai — 统一 LLM API <a class="header-anchor" href="#pi-ai-—-统一-llm-api" aria-label="Permalink to &quot;pi-ai — 统一 LLM API&quot;">​</a></h3><p>跨 provider 的统一接口，仅需对接 <strong>4 种 API</strong> 即可覆盖几乎所有 LLM provider：</p><ul><li>OpenAI Completions API</li><li>OpenAI Responses API</li><li>Anthropic Messages API</li><li>Google Generative AI API</li></ul><p><strong>关键特性</strong>：</p><ul><li>跨 provider context handoff：可在 Anthropic / OpenAI / Google 模型之间无缝切换，thinking traces 会以 <code>&lt;thinking&gt;&lt;/thinking&gt;</code> 标签形式传递</li><li>Token 和成本追踪（best-effort）</li><li>完整的测试套件，覆盖所有 provider 和热门模型</li><li>支持自托管（ollama、vLLM、LM Studio 等）</li><li>同样可在浏览器中运行（感谢 Anthropic 和 xAI 的 CORS 支持）</li></ul><h3 id="pi-agent-core-—-agent-循环" tabindex="-1">pi-agent-core — Agent 循环 <a class="header-anchor" href="#pi-agent-core-—-agent-循环" aria-label="Permalink to &quot;pi-agent-core — Agent 循环&quot;">​</a></h3><p>处理完整的 agent 编排：处理用户消息、执行 tool calls、反馈结果给 LLM、循环直到模型不再调用 tool。</p><p>提供实用的 Agent 类：状态管理、简化的事件订阅、attachment 处理（图片、文档）、transport 抽象（支持直接运行或通过 proxy）。</p><p><strong>故意不做的事</strong>：</p><ul><li>没有 max steps 限制——循环直到 agent 说完成</li><li>没有 plan mode</li><li>没有 MCP support</li><li>没有 background bash</li><li>没有 sub-agents</li><li><strong>YOLO by default</strong></li></ul><h3 id="pi-tui-—-终端-ui-框架" tabindex="-1">pi-tui — 终端 UI 框架 <a class="header-anchor" href="#pi-tui-—-终端-ui-框架" aria-label="Permalink to &quot;pi-tui — 终端 UI 框架&quot;">​</a></h3><p>采用<strong>保留模式 UI</strong>（retained mode），区别于 Claude Code/Codex/Droid 的追加写入模式。</p><p><strong>差异化设计</strong>：</p><ul><li>完整保留终端 scrollback buffer（用户可以使用原生搜索、滚动）</li><li><strong>微差分渲染</strong>（Differential rendering）：只重绘变化的行</li><li>使用 ANSI escape sequence <code>CSI ?2026h/l</code> 实现同步输出，防止闪烁</li><li>支持 markdown 渲染和代码高亮</li></ul><h3 id="pi-coding-agent-—-cli" tabindex="-1">pi-coding-agent — CLI <a class="header-anchor" href="#pi-coding-agent-—-cli" aria-label="Permalink to &quot;pi-coding-agent — CLI&quot;">​</a></h3><p>整合所有组件，提供完整的 coding agent 体验：</p><ul><li>多 provider 支持，支持 session 中切换模型</li><li>Session 管理（continue / resume / branching）</li><li>项目级上下文文件（AGENTS.md），支持从全局到项目级的层级加载</li><li>Slash commands 和自定义模板</li><li>OAuth 认证支持（Claude Pro/Max）</li></ul><p><strong>刻意省略的设计决策</strong>：</p><table tabindex="0"><thead><tr><th>不做</th><th>原因</th></tr></thead><tbody><tr><td>内置 to-dos</td><td>外部工具更适合</td></tr><tr><td>Plan mode</td><td>预测行为不可靠</td></tr><tr><td>MCP support</td><td>增加复杂性和不确定性</td></tr><tr><td>Background bash</td><td>透明性优先</td></tr><tr><td>Sub-agents</td><td>增加不可预测性</td></tr><tr><td>YOLO by default</td><td>不做假设，让用户控制</td></tr></tbody></table><h2 id="与现有工具的差异化定位" tabindex="-1">与现有工具的差异化定位 <a class="header-anchor" href="#与现有工具的差异化定位" aria-label="Permalink to &quot;与现有工具的差异化定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Claude Code</th><th>Cursor</th><th>Pi Agent</th></tr></thead><tbody><tr><td>哲学</td><td>功能丰富</td><td>All-in-one IDE</td><td>极简、可预测</td></tr><tr><td>透明性</td><td>注入内容不 surface</td><td>中等</td><td>完全可检查</td></tr><tr><td>API 稳定性</td><td>系统 prompt 频繁变更</td><td>商业闭源</td><td>固执设计</td></tr><tr><td>自托管</td><td>一般</td><td>不支持</td><td>良好支持</td></tr><tr><td>Context 控制</td><td>困难</td><td>困难</td><td><strong>精确控制</strong></td></tr><tr><td>UI 模式</td><td>追加写入</td><td>GUI</td><td>差分渲染 + scrollback</td></tr></tbody></table><h2 id="开发者友好的设计要点" tabindex="-1">开发者友好的设计要点 <a class="header-anchor" href="#开发者友好的设计要点" aria-label="Permalink to &quot;开发者友好的设计要点&quot;">​</a></h2><ol><li><strong>Clean API</strong>：相比 Vercel AI SDK 的&quot;有机演进&quot;式 API，pi-mono 从一开始就是干净设计，没有 backwards compatibility 包袱</li><li><strong>Context engineering first</strong>：这是核心洞察——精确控制 context 内容比增加更多 tool 更重要</li><li><strong>Structured split tool results</strong>：tool 可以返回 LLM 内容和 UI 显示内容的分离，避免解析文本再重构</li><li><strong>Partial JSON parsing</strong>：tool call arguments 流式解析时渐进展示 partial results</li><li><strong>Abort 支持</strong>：完整的请求中止支持，包括 tool call 层面</li><li><strong>Session 可序列化</strong>：context 可 JSON 序列化/反序列化，支持存储、传输、后续继续</li><li><strong>无 max steps 限制</strong>：agent 自己决定何时完成，而不是被步数限制强制中断</li></ol><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://github.com/badlogic/pi-mono" target="_blank" rel="noreferrer">GitHub: badlogic/pi-mono</a></li><li><a href="https://github.com/badlogic/pi-mono/tree/main/packages/coding-agent" target="_blank" rel="noreferrer">pi-coding-agent</a></li><li><a href="https://github.com/badlogic/pi-mono/tree/main/packages/ai" target="_blank" rel="noreferrer">pi-ai</a></li><li><a href="https://github.com/badlogic/pi-mono/tree/main/packages/agent" target="_blank" rel="noreferrer">pi-agent-core</a></li><li><a href="https://github.com/badlogic/pi-mono/tree/main/packages/tui" target="_blank" rel="noreferrer">pi-tui</a></li><li><a href="https://mariozechner.at/posts/2025-11-30-pi-coding-agent/" target="_blank" rel="noreferrer">原文博客</a></li></ul>',41)])])}const f=a(o,[["render",n]]);export{m as __pageData,f as default};
